const BG: Record<string, string> = {
};

function PptxSlide({ id, step }: { id: string; step: number }) {
  return (
    <div
      className="pptx"
      data-cur={step}
      style={BG[id] ? ({ '--bg': BG[id] } as React.CSSProperties) : undefined}
      dangerouslySetInnerHTML={{ __html: HTML[id] ?? '' }}
    />
  );
}

